import json
from pathlib import Path
base='#include <iostream>\n#include <string>\nusing namespace std;\n'
def main(body):return base+'int main() {\n'+body+'\n  return 0;\n}'
data={}
def add(i,code,out,scene,explain,predict,change,mistake,recap,stdin=None):
 x=dict(example=code,output=out,steps=[['الفكرة في موقف',scene],['نفك البرنامج معًا',explain],['توقّع ثم جرّب',predict],['غيّر شيئًا واحدًا',change]],mistake=mistake,recap=recap)
 if stdin:x['stdin']=stdin
 data['cpp_l'+str(i)]=x
add(6,main('  int score = 10;\n  if (score >= 10) {\n    cout << "Unlocked" << endl;\n  }\n  cout << "Done" << endl;'),'Unlocked\nDone','تفتح مرحلة عندما تبلغ النقاط10. لا تريد عرض الفتح لكل لاعب.','if تفحص المقارنة داخل الأقواس. عند صحتها تنفذ الكتلة. Done خارج الكتلة، لذلك تظهر مهما كانت النتيجة.','النقاط10 تحقق >= 10. توقع رسالتين قبل التشغيل ثم قارن.','غيّر score إلى9. توقع اختفاء Unlocked وبقاء Done ثم شغّل.','لا تضع ; مباشرة بعد شرط if. استخدم == للمساواة لا = التي تعني الإسناد.','الشرط يتحكم في كتلة محددة، لا كل ما يأتي بعده.')
add(7,main('  int grade = 45;\n  if (grade >= 50) {\n    cout << "Pass" << endl;\n  } else {\n    cout << "Try again" << endl;\n  }'),'Try again','نتيجة الاختبار لها رسالة نجاح ورسالة بديلة. الفرع البديل يمنع ترك حالة دون رد.','عند45 يفشل >= 50، فينفذ else. إذا تحقق الشرط ينفذ if وحدها.','أي فرع ينفذ؟ توقع Try again ثم شغّل. فكر بعد ذلك في الدرجة50.','غيّر45 إلى50 فقط. توقع Pass لأن المقارنة تشمل الحد نفسه.','else لا تأخذ شرطًا جديدًا. لا تستخدم if ثانية إذا كنت تقصد بديلًا حصريًا.','if وelse تختاران فرعًا واحدًا من اثنين.')
add(8,main('  int grade = 75;\n  if (grade >= 90) cout << "Excellent" << endl;\n  else if (grade >= 70) cout << "Good" << endl;\n  else cout << "Practice" << endl;'),'Good','تريد ثلاثة تقديرات حسب الدرجة. نفحص الحد الأعلى أولًا ثم ننتقل للأقل.','75 تفشل شرط90 وتحقق شرط70، فينفذ Good. لا تستمر السلسلة بعد أول فرع صحيح.','توقع ناتج75 و95 و60 على الورق، ثم شغّل الحالة الموجودة.','غيّر الدرجة إلى95. بعدها فكر: لماذا وضع >=70 أولًا قد يحجب Excellent؟','ترتيب المقارنات المتداخلة مهم؛ أول فرع صحيح يفوز.','ابدأ بالحالة الأكثر تقييدًا عندما تتداخل حدود الدرجات.')
add(9,main('  for (int i = 1; i <= 3; i++) {\n    cout << i << endl;\n  }'),'1\n2\n3','تريد عرض الأعداد دون نسخ أمر الطباعة لكل عدد. العداد يعطيك تكرارًا منظمًا.','int i = 1 بداية مرة واحدة. الشرط قبل كل دورة، وi++ تحديث بعد الجسم. عند4 ينتهي التكرار.','اكتب تسلسل1،2،3 ثم توقع عدد الأسطر قبل التشغيل.','بدّل <= إلى < فقط. هل يظهر3؟ توقع سطرين ثم تحقق.','عداد يبدأ0 مع <=3 يعطي أربع دورات، لا ثلاثًا.','حدد أول قيمة وآخر قيمة، ثم اختر الشرط والتحديث.')
add(10,main('  int energy = 3;\n  while (energy > 0) {\n    cout << energy << endl;\n    energy--;\n  }'),'3\n2\n1','يستمر التدريب ما دامت الطاقة موجبة. عدد الدورات يعتمد على حالة تتغير.','نفحص >0 ثم نطبع وننقص الطاقة. عندما تصل0 نخرج قبل طباعة0.','تتبع الطاقة قبل كل دورة، ثم شغّل وقارن ثلاثة أسطر.','غيّر البداية إلى0، وتوقع ألا يظهر شيء. لا تحذف سطر الإنقاص.','نسيان التحديث قد يصنع حلقة لا تنتهي. تأكد أن الجسم يقرب الشرط من false.','while تختبر قبل التنفيذ، وقد لا تنفذ أي دورة.')
add(11,main('  for (int i = 1; i <= 5; i++) {\n    if (i == 2) continue;\n    if (i == 4) break;\n    cout << i << endl;\n  }'),'1\n3','تريد تخطي قيمة واحدة ثم إيقاف العد عند حد آخر. التخطي غير الخروج النهائي.','continue عند2 تقفز للتحديث في for. break عند4 تخرج من الحلقة، فلا يصل5 للطباعة.','اشطب2 من التتبع، وتوقف قبل طباعة4. توقع1 ثم3 وشغّل.','احذف سطر break فقط. توقع ظهور4 و5 أيضًا.','في while قد تتجاوز continue تحديث العداد إذا وضعته بعدها، فتسبب تكرارًا لا ينتهي.','continue للدورة التالية، وbreak لإنهاء الحلقة.')
add(12,base+'void sayHi() {\n  cout << "Hello" << endl;\n}\nint main() {\n  sayHi();\n  sayHi();\n  return 0;\n}','Hello\nHello','تكرر نفس التحية في أكثر من موضع. الدالة تجمع الفعل باسم مفهوم.','void تعني أن الدالة لا تعيد قيمة. تعريف sayHi قبل main يجعل اسمها معروفًا قبل الاستدعاء. كل sayHi() تنفذ الجسم مرة.','لا تعد التعريف كتشغيل. توقع سطرين بسبب الاستدعاءين ثم شغّل.','احذف استدعاءً واحدًا فقط. سيبقى التعريف لكن ينفذ مرة.','تعريف الدالة داخل main ليس طريقة صحيحة لتعريف دالة عادية في C++.','عرّف الدالة ثم استدعها، وافصل تنظيم الخطوات عن تشغيلها.')
add(13,base+'void greet(string name) {\n  cout << "Hello " << name << endl;\n}\nint main() {\n  greet("Cody");\n  greet("Mona");\n  return 0;\n}','Hello Cody\nHello Mona','التحية ثابتة لكن الشخص يتغير. المدخل يجعل نفس الدالة تعمل لقيم متعددة.','string name معامل يستقبل نص كل استدعاء. الاسم داخل الدالة يستخدم القيمة المرسلة، لا كلمة name حرفيًا.','توقع ترتيب الرسالتين حسب ترتيب الاستدعاء ثم شغّل.','غيّر Mona في الاستدعاء إلى اسمك دون تعديل الجسم.','عدد الوسائط وأنواعها يجب أن يناسبا المعاملات. إرسال نص لدالة تنتظر int ليس نفس المثال.','المعامل يحدد نوع المدخل واسمه داخل الدالة.')
add(14,base+'int add(int a, int b) {\n  return a + b;\n}\nint main() {\n  int total = add(2, 3);\n  cout << total * 2 << endl;\n  return 0;\n}','10','تريد إعادة نتيجة الجمع لتدخل في حساب آخر بدل عرضها فورًا.','نوع الإرجاع int يعلن أن الناتج عدد صحيح. return تعيد5 وتنهي الاستدعاء. main تضرب الناتج في2 قبل العرض.','الدالة لا تطبع5 هنا. توقع10 من أمر cout الوحيد ثم شغّل.','بدّل الضرب2 إلى3. ستظل نتيجة add خمسة لكن العرض يصبح15.','دالة غير void يجب أن تعيد قيمة مناسبة في كل مسار مطلوب. الطباعة لا تغني عن return.','قيمة الإرجاع نتيجة قابلة لإعادة الاستخدام.')
add(15,main('  int scores[3] = {10, 20, 30};\n  cout << scores[0] << endl;\n  cout << scores[2] << endl;'),'10\n30','قائمة درجات مترابطة تحتاج ترتيبًا ومكانًا لكل عنصر. المصفوفة تخزن عناصر من النوع نفسه.','[3] يحدد عدد العناصر. الفهارس الصحيحة0 و1 و2. scores[2] يقرأ العنصر الثالث.','ضع فهرسًا فوق كل قيمة ثم توقع السطرين قبل التشغيل.','بدّل الفهرس2 إلى1 فقط. توقع20 ثم تحقق. لا تجرب الفهرس3.','تجاوز حدود مصفوفة C++ سلوك غير معرّف، وليس مضمونًا أن يعطي رسالة خطأ أو undefined.','مصفوفة من3 عناصر تنتهي عند الفهرس2.')
add(16,main('  string name = "Cody";\n  name += " Academy";\n  cout << name << endl;\n  cout << name.length() << endl;'),'Cody Academy\n12','تريد تكوين اسم عرض من نصين، ثم حساب طوله. string تقدم أدوات للعمل مع النص.','+= تضيف النص إلى name. length() دالة عضو تُستدعى بأقواس. المسافة المضافة تحسب ضمن الطول.','توقع Cody Academy ثم12، وعد المسافة عند حساب الطول. شغّل للمقارنة.','غيّر الجزء المضاف إلى نص إنجليزي أقصر، ثم توقع الطول الجديد.','std::string.length تحسب وحدات char؛ النص العربي بترميز UTF-8 قد يأخذ عدة بايتات للحرف الواحد.','ضم النصوص وحساب طولها عمليتان مختلفتان، وانتبه للترميز.')
add(17,main('  int scores[3] = {10, 20, 30};\n  int total = 0;\n  for (int i = 0; i < 3; i++) {\n    total += scores[i];\n  }\n  cout << total << endl;'),'60','تريد جمع كل الدرجات بدل كتابة كل عنصر يدويًا. نستخدم العداد كفهرس للمصفوفة.','total يبدأ0. لكل i صحيح نضيف scores[i]. تتتابع المجاميع10 ثم30 ثم60. الشرط i < 3 يحمي حدود القائمة.','اكتب قيمة total بعد كل دورة ثم شغّل وتحقق من60.','غيّر العنصر الأوسط20 إلى25 فقط. توقع65 قبل التشغيل.','i <= 3 سيحاول الوصول لعنصر خارج الحدود. لا تغيّر الشرط لهذا الشكل.','الحلقة تربط فهرسًا صحيحًا بكل عنصر، والمجمّع يحتفظ بالنتيجة.')
add(18,main('  int score = 10;\n  int& alias = score;\n  alias = 25;\n  cout << score << endl;'),'25','تريد اسمًا ثانيًا يشير لنفس المتغير، لا نسخة مستقلة منه. المرجع يحقق ذلك.','int& alias = score يربط alias بنفس score. الإسناد للاسم الثاني يغيّر القيمة المشتركة، لذلك تظهر25.','هل يبقى score عشرة؟ توقع25 لأنك لم تنشئ نسخة، ثم شغّل.','بدّل int& إلى int لتجعل alias نسخة. توقع بقاء score عشرة بعد تعديل النسخة.','المرجع يجب تهيئته عند إنشائه هنا، ولا يمكن تحويله لاحقًا لمرجع لمتغير آخر بمجرد الإسناد.','المرجع اسم بديل لنفس الكائن، لا صندوق قيم جديد.')
add(19,main('  int score = 10;\n  int* ptr = &score;\n  cout << *ptr << endl;\n  cout << (ptr == &score) << endl;'),'10\n1','تحتاج متغيرًا يحتفظ بعنوان متغير آخر. المؤشر يحمل العنوان، وفك الإشارة يصل للقيمة.','&score يأخذ عنوان score. int* يعلن مؤشرًا لعدد صحيح. *ptr تقرأ العدد عند ذلك العنوان، والمقارنة تعرض1 لأن العنوانين متساويان.','ميّز ptr عن *ptr قبل التشغيل: الأول عنوان، والثاني القيمة10. المثال لا يطبع العنوان المتغير من تشغيل لآخر.','غيّر score إلى30 قبل الطباعة. توقع أن تقرأ *ptr القيمة الجديدة دون إعادة ربط المؤشر.','لا تفك إشارة مؤشر غير مهيأ أو فارغ. العنوان ليس نفس القيمة المخزنة عنده.','& يأخذ عنوانًا، و* عند الاستخدام تفك إشارة المؤشر.')
add(20,main('  int score = 10;\n  int* ptr = &score;\n  *ptr = 40;\n  cout << score << endl;'),'40','تريد تغيير قيمة من خلال عنوانها. نكتب في الكائن المشار إليه بدل تغيير العنوان.','*ptr = 40 تخزن40 داخل score. أما ptr نفسه فيظل يشير إلى score. نجمة التصريح ونجمة فك الإشارة مرتبطتان لكن في موضعين مختلفين.','توقع قيمة score بعد التعديل غير المباشر ثم شغّل.','بدّل40 إلى55 في سطر *ptr فقط. لاحظ أن score يظهر55.','ptr = 40 ليس بديلًا عن *ptr = 40؛ الأول يحاول إسناد عدد إلى مؤشر ولا يعبّر عن نفس العملية.','التعديل عبر مؤشر صالح يؤثر في الكائن الأصلي.')
add(21,main('  int* ptr = nullptr;\n  if (ptr != nullptr) {\n    cout << *ptr << endl;\n  } else {\n    cout << "No value" << endl;\n  }'),'No value','قد لا يوجد عنوان صالح بعد. nullptr تعني أن المؤشر لا يشير لكائن، فنفحصه قبل القراءة.','المقارنة false لأن ptr فارغ. لذلك لا ينفذ *ptr، ويصل البرنامج للفرع البديل الآمن.','توقع No value دون محاولة قراءة قيمة غير موجودة. شغّل المثال كما هو.','أنشئ int score = 8 ثم غيّر التهيئة إلى int* ptr = &score. توقع8 بعد التحقق.','فك إشارة nullptr سلوك غير معرّف. لا تحذف شرط الحماية لتجربته.','null ليس قيمة بيانات في الكائن؛ هو غياب عنوان صالح.')
add(22,main('  int grades[3] = {80, 90, 85};\n  int total = 0;\n  for (int i = 0; i < 3; i++) total += grades[i];\n  double average = total / 3.0;\n  cout << average << endl;'),'85','متوسط الدرجات يجمع القائمة ثم يقسم على عددها. مشروع صغير يجمع المصفوفة والحلقة والحساب.','total يصل255. استخدام3.0 يجعل القسمة عشرية قبل تخزينها في double. العدد3 هنا يطابق حجم المصفوفة.','احسب80+90+85 ثم اقسم على3، وتوقع85 قبل التشغيل.','غيّر85 في المصفوفة إلى86. المتوسط يصبح85.3333 تقريبًا؛ لاحظ عرض cout الافتراضي.','قسمة int على int تفقد الجزء الكسري قبل إسناده إلى double. لا تقسّم مجموعًا على عدد عناصر صفر.','احسب المجموع بحلقة ثم اقسم قسمة مناسبة لنتيجة عشرية.')
add(23,main('  double a = 0, b = 0;\n  char op;\n  cin >> a >> op >> b;\n  if (op == \'+\') cout << a + b << endl;\n  else if (op == \'-\') cout << a - b << endl;\n  else if (op == \'*\') cout << a * b << endl;\n  else if (op == \'/\' && b != 0) cout << a / b << endl;\n  else cout << "Invalid operation" << endl;'),'4','آلة حاسبة تقرأ عددًا ثم رمز العملية ثم عددًا آخر. اكتب8 / 2 في المدخلات لتجربتها.','double تحفظ أعدادًا عشرية وchar تحفظ رمزًا واحدًا. الشروط تختار العملية، والقسمة تحتاج b != 0 حتى لا تقسم على صفر.','توقع4 للمدخل8 / 2، ثم شغّل. تتبع أي شرط يصل إلى true.','أبق الكود وغيّر المدخلات إلى8 / 0. توقع رسالة Invalid operation بدل حساب غير صالح.','ترتيب المدخلات مهم: عدد ثم رمز ثم عدد. الرموز المفردة توضع بين اقتباس مفرد في مقارنات char.','اجمع القراءة والاختيار والتحقق من المدخلات في برنامج واحد.',stdin='8 / 2\n')
Path('/tmp/guided-cpp-rest.json').write_text(json.dumps(data,ensure_ascii=False))
print(len(data),'original C++ lessons staged')
